Looking at the code again:

```c
static const char *
read_long_names (Elf *elf)
{
  off_t offset = SARMAG;
  struct ar_hdr hdrm;
  struct ar_hdr *hdr;
  char *newp;
  size_t len;

  while (1)
    {
      if (elf->map_address != NULL)
        {
          if ((size_t) offset > elf->maximum_size
              || elf->maximum_size - offset < sizeof (struct ar_hdr))
            return NULL;

          hdr = (struct ar_hdr *) (elf->map_address + offset);
        }
      ...
      len = atol (string);

      if (memcmp (hdr->ar_name, "//              ", 16) == 0)
        break;

      offset += sizeof (struct ar_hdr) + ((len + 1) & ~1l);
    }
  ...
}
```

The key issue: `offset` is `off_t` (signed 64-bit). If `len` is negative and even, `(len + 1) & ~1l` is a huge positive number. Adding this to `offset` can cause `offset` to overflow.

